# region: render
def render(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: digest
def digest(xs):
    return [v for v in xs if v % 2 == 0]

# region: sift
def sift(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: emit
def emit(xs, factor=2):
    return [v * factor for v in xs]

# region: gather
def gather(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: fold
def fold(summary, bar=4):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return fold(gather(emit(sift(digest(render(raw))))))

